basic.css:
.card {
  --fg: #1a1a1a;
  --bg: #fdfdfd;
  --code-bg: #f0f0f2;
  --rule: #b9b9c0;
  --accent: #2b6cb0;
  font-family: -apple-system, Segoe UI, Roboto, sans-serif;
  font-size: 18px;
  text-align: left;
  color: var(--fg);
  background-color: var(--bg);
  padding: 12px 18px;
}
.card.nightMode, .card.night_mode {
  --fg: #e8e8ea;
  --bg: #2c2c2e;
  --code-bg: #3a3a3d;
  --rule: #6b6b73;
  --accent: #8ab4f8;
}
code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.92em;
  color: var(--fg);
  background: var(--code-bg);
  border-radius: 3px;
  padding: 1px 4px;
}
.code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.9em;
  color: var(--fg);
  background: var(--code-bg);
  border-left: 3px solid var(--rule);
  border-radius: 3px;
  padding: 10px 12px;
  margin: 8px 0;
  white-space: normal;
  overflow-x: auto;
}
.code code { background: none; padding: 0; }
.cloze { font-weight: bold; color: var(--accent); }
hr#answer { margin: 14px 0; border: none; border-top: 1px solid var(--rule); }

